from django.db import migrations


# as duas tabelas de log que vão ficar protegidas
TABELAS = ['autenticacao_logauditoria', 'autenticacao_logautenticacao']

# colunas que nunca podem mudar em cada tabela (usuario_id só pode virar NULL, ver abaixo)
# só é usado no sqlite, que é o banco dos testes locais
COLUNAS_SQLITE = {
    'autenticacao_logauditoria': ['acao', 'risco', 'ip_origem', 'detalhes', 'data_hora'],
    'autenticacao_logautenticacao': ['ra_registrado', 'evento', 'ip', 'data_hora'],
}

# função do postgres que o gatilho chma toda vez que alguém tenta mexer num log
# o $$ delimita o corpo da função, e o % dentro do RAISE é substituído pelo nome da tabela
FUNCAO_POSTGRES = """
CREATE OR REPLACE FUNCTION bloquear_alteracao_log() RETURNS trigger AS $$
BEGIN
    -- apagar um log nunca é permitido
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Logs são imutáveis: exclusão bloqueada em %', TG_TABLE_NAME;
    END IF;

    -- única mudança aceita: o usuário ser apagado e o Django zerar o usuario_id (SET_NULL)
    -- se o usuario_id não ficou nulo, ou se qualquer outra coluna mudou, recusa
    IF NEW.usuario_id IS NOT NULL
       OR (to_jsonb(NEW) - 'usuario_id') IS DISTINCT FROM (to_jsonb(OLD) - 'usuario_id') THEN
        RAISE EXCEPTION 'Logs são imutáveis: alteração bloqueada em %', TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""


def criar_gatilhos(apps, schema_editor):
    # descobre se está rodndo no postgres ou no sqlite, porque cada um tem uma sintaxe
    banco = schema_editor.connection.vendor

    if banco == 'postgresql':
        # cria a função (params=None porque o % do RAISE não é um parâmetro do Django)
        schema_editor.execute(FUNCAO_POSTGRES, params=None)
        for tabela in TABELAS:
            # remove o gatilho antigo, se existir, para a migration poder rodar de novo sem erro
            schema_editor.execute(f'DROP TRIGGER IF EXISTS {tabela}_imutavel ON {tabela};')
            # liga a função à tabela: roda antes de qualquer UPDATE ou DELETE, linha por linha
            schema_editor.execute(
                f'CREATE TRIGGER {tabela}_imutavel BEFORE UPDATE OR DELETE ON {tabela} '
                f'FOR EACH ROW EXECUTE FUNCTION bloquear_alteracao_log();'
            )

    elif banco == 'sqlite':
        # no sqliteo mesmo bloqueio, escrito do jeito do sqlite
        for tabela in TABELAS:
            # monta a condição "alguma coluna mudou" a partir da lista de colunas da tabela
            mudou = ' OR '.join(f'NEW.{c} IS NOT OLD.{c}' for c in COLUNAS_SQLITE[tabela])
            # gatilho que barra qualquer DELETE
            schema_editor.execute(
                f'CREATE TRIGGER {tabela}_sem_delete BEFORE DELETE ON {tabela} '
                f"BEGIN SELECT RAISE(ABORT, 'Logs são imutáveis'); END;"
            )
            # gatilho que barra UPDATE, menos quando só o usuario_id está virando nulo
            schema_editor.execute(
                f'CREATE TRIGGER {tabela}_sem_update BEFORE UPDATE ON {tabela} '
                f'WHEN NEW.usuario_id IS NOT NULL OR {mudou} '
                f"BEGIN SELECT RAISE(ABORT, 'Logs são imutáveis'); END;"
            )


def remover_gatilhos(apps, schema_editor):
    # desfaz a migration tirando os gatilhos
    banco = schema_editor.connection.vendor

    if banco == 'postgresql':
        for tabela in TABELAS:
            schema_editor.execute(f'DROP TRIGGER IF EXISTS {tabela}_imutavel ON {tabela};')
        # a função só pode ser apagada depois que os gatilhos que usam ela saíram
        schema_editor.execute('DROP FUNCTION IF EXISTS bloquear_alteracao_log();')

    elif banco == 'sqlite':
        for tabela in TABELAS:
            schema_editor.execute(f'DROP TRIGGER IF EXISTS {tabela}_sem_delete;')
            schema_editor.execute(f'DROP TRIGGER IF EXISTS {tabela}_sem_update;')


